from pathlib import Path
import json
root=Path(__file__).resolve().parent
bank=json.loads((root/'question-bank.json').read_text())
page='''<!doctype html>
<html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>SOC3050 · ARM midterm practice</title>
<style>
:root{color-scheme:light dark;--bg:#f4f6f9;--card:#fff;--ink:#17263b;--muted:#536177;--line:#d9e0ea;--accent:#164ba5;--good:#14733d;--bad:#b12c30}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:17px/1.6 system-ui,sans-serif}main{max-width:1040px;margin:auto;padding:30px 22px 80px}h1{font-size:clamp(28px,5vw,46px);line-height:1.15;letter-spacing:-.035em;margin:.2em 0}h2{font-size:25px}h3{font-size:20px}p{margin:.7em 0}.eyebrow{color:var(--accent);font-weight:700;font-size:13px;letter-spacing:.12em}.muted,small{color:var(--muted)}a{color:var(--accent)}.card,fieldset{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:24px;margin:20px 0}fieldset{min-width:0}legend{font-weight:700;padding:0 8px}button,select{font:inherit;border:1px solid var(--line);border-radius:8px;padding:9px 15px;background:var(--card);color:var(--ink)}button{cursor:pointer}button.primary{background:var(--accent);color:#fff;border-color:var(--accent)}button:disabled{opacity:.55;cursor:default}.controls{display:flex;gap:14px;align-items:end;flex-wrap:wrap}.controls label{display:grid;gap:5px}.bar{position:sticky;top:0;z-index:5;display:flex;gap:20px;justify-content:space-between;align-items:center;background:var(--card);padding:13px 20px;border-bottom:1px solid var(--line);flex-wrap:wrap}.time{font:700 24px ui-monospace,monospace;font-variant-numeric:tabular-nums}.option{display:flex;align-items:baseline;gap:10px;padding:12px;border:1px solid var(--line);border-radius:8px;margin:10px 0;cursor:pointer;overflow-wrap:anywhere}.option:has(input:checked){border-color:var(--accent);background:color-mix(in srgb,var(--accent) 7%,var(--card))}.option.correct,.option.correct:has(input:checked){border:2px solid var(--good);color:var(--good);background:color-mix(in srgb,var(--good) 14%,var(--card))}.option.wrong,.option.wrong:has(input:checked){border:2px solid var(--bad);color:var(--bad);background:color-mix(in srgb,var(--bad) 10%,var(--card))}.option:has(input:disabled){cursor:default}input{accent-color:var(--accent);flex-shrink:0}.stem{white-space:pre-wrap;font-weight:550}.explanation{border-top:1px solid var(--line);padding-top:14px;margin-top:20px}.good{color:var(--good)}.bad{color:var(--bad)}.nav{display:flex;gap:7px;flex-wrap:wrap}.nav a{padding:4px 10px;border:1px solid var(--line);border-radius:6px;text-decoration:none}.nav a.answered{background:var(--accent);color:white}table{border-collapse:collapse;width:100%}td,th{text-align:left;border-bottom:1px solid var(--line);padding:9px}.score{font-size:44px;font-weight:750}fieldset,#result{scroll-margin-top:95px}button:focus-visible,a:focus-visible,select:focus-visible,input:focus-visible{outline:3px solid #d78d16;outline-offset:3px}[hidden]{display:none!important}.footer{display:flex;gap:12px;flex-wrap:wrap}
@media(prefers-color-scheme:dark){:root{--bg:#111924;--card:#192331;--ink:#e5edf8;--muted:#a4b4cb;--line:#344458;--accent:#88b3ff;--good:#74d999;--bad:#ff9696}button.primary{color:#111924}}
@media(max-width:600px){main{padding:22px 14px}fieldset,.card{padding:17px}.bar{gap:10px;padding:10px 14px;font-size:14px}.time{font-size:21px}.option{padding:10px;font-size:16px}}
@media print{.bar,.controls,.nav,.footer,#intro{display:none}body{background:white;color:black}main{padding:0;max-width:none}.card,fieldset{break-inside:avoid;border-radius:0}.option{padding:5px;margin:5px 0}a{color:inherit}}
</style>
<div id="statusbar" class="bar" hidden><strong id="examname"></strong><span id="progress" role="status"></span><span id="timer" class="time" aria-label="Осталось времени"></span><button id="finishTop" class="primary">Завершить</button></div>
<main><header><div class="eyebrow">SOC3050 · ARM 2026 · LESSONS 00–08</div><h1>Practice midterm</h1><p class="muted">99 авторских вопросов · 3 варианта · английские задания и русский разбор</p></header>
<section id="intro" class="card"><p>Официальный формат: <strong>33 вопроса за 60 минут</strong>, один ответ A–D, без калькулятора. Это тренировка по материалам преподавателя, а не официальный экзамен.</p><p>После выбора правильный вариант сразу станет зелёным, остальные — красными, и откроется объяснение. Первый ответ фиксируется для итогового балла. В режиме экзамена есть таймер на 60 минут; в тренировке таймера нет. Состояние хранится только в открытой вкладке: обновление страницы сбросит попытку.</p><div class="controls"><label>Вариант<select id="variant"><option>A</option><option>B</option><option>C</option></select></label><label>Режим<select id="mode"><option value="exam">Экзамен · 60 минут</option><option value="practice">Тренировка · без таймера</option></select></label><button id="start" class="primary">Начать</button></div><p><small>Для работы интернет не нужен. <a href="Study-guide-RU.html">Конспект</a> · <a href="index.html">Все материалы</a></small></p></section>
<section id="result" class="card" hidden aria-live="polite"></section><section id="jump" class="card" hidden><strong>Вопросы</strong><nav id="nav" class="nav" aria-label="Номера вопросов"></nav></section><form id="questions"></form><div id="bottom" class="footer" hidden><button id="finishBottom" class="primary">Завершить и посмотреть разбор</button><button id="again" hidden>Новая попытка</button></div><p class="muted"><small>Источник: gnoejh/soc3050code, commit 7906b2fdc7895f9656402033bb5af66f5fd3eee8. Подготовлено 27.10.2026. Балл — диагностика понимания, не прогноз оценки.</small></p></main>
<script id="bank" type="application/json">__BANK__</script>
<script>
'use strict';
const bank=JSON.parse(document.getElementById('bank').textContent);
const $=id=>document.getElementById(id);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const titles=["Programmer model",'Instruction set','Development','Concurrency','Startup and linker','GPIO and interrupts','Time and timers','RTOS','UART and Python'];
let current=[],answers={},submitted=false,interval=null,deadline=0;
function updateProgress(){const n=Object.keys(answers).length;$('progress').textContent=`Ответов ${n} / ${current.length}`;for(const x of current){const a=$('nav-'+x.id);a.classList.toggle('answered',answers[x.id]!==undefined)}}
function tick(){if(submitted)return;const remaining=Math.max(0,Math.ceil((deadline-Date.now())/1000));$('timer').textContent=`${String(Math.floor(remaining/60)).padStart(2,'0')}:${String(remaining%60).padStart(2,'0')}`;if(!remaining)finish('Время истекло.');}
function start(){clearInterval(interval);current=bank.filter(x=>x.variant===$('variant').value);answers={};submitted=false;$('intro').hidden=true;$('statusbar').hidden=false;$('jump').hidden=false;$('result').hidden=true;$('bottom').hidden=false;$('finishBottom').hidden=false;$('finishTop').hidden=false;$('again').hidden=true;$('examname').textContent='Вариант '+$('variant').value;$('nav').innerHTML=current.map(x=>`<a id="nav-${x.id}" href="#q-${x.id}">${x.number}</a>`).join('');$('questions').innerHTML=current.map(x=>`<fieldset id="q-${x.id}"><legend>Question ${x.number}</legend><p class="stem">${esc(x.stem)}</p>${x.options.map((o,i)=>`<label class="option" id="option-${x.id}-${i}"><input type="radio" name="${x.id}" value="${i}"><span><strong>${'ABCD'[i]}.</strong> ${esc(o)}</span></label>`).join('')}<div id="explain-${x.id}" class="explanation" aria-live="polite" hidden></div></fieldset>`).join('');updateProgress();if($('mode').value==='exam'){deadline=Date.now()+60*60*1000;tick();interval=setInterval(tick,250)}else{$('timer').textContent='Без таймера'}window.scrollTo({top:0});}
function revealAnswer(x){const selected=answers[x.id],ok=selected===x.answer;for(let i=0;i<x.options.length;i++){const option=$('option-'+x.id+'-'+i);option.classList.add(i===x.answer?'correct':'wrong');option.querySelector('input').disabled=true}const el=$('explain-'+x.id);el.hidden=false;el.innerHTML=`<strong class="${ok?'good':'bad'}">${ok?'Верно':selected===undefined?'Без ответа':'Ошибка'} · Ответ ${'ABCD'[x.answer]}</strong><p>${esc(x.why)}</p><small><a href="${esc(x.source)}">Lesson ${x.lesson}, slides ${esc(x.slides)}</a></small>`}
function finish(reason='Попытка завершена.'){if(submitted)return;submitted=true;clearInterval(interval);let score=0;const stats=Array.from({length:9},()=>({correct:0,total:0,miss:[]}));for(const x of current){const selected=answers[x.id],ok=selected===x.answer,s=stats[Number(x.lesson)];s.total++;if(ok){score++;s.correct++}else{s.miss.push(x.number)}revealAnswer(x)}document.querySelectorAll('#questions input').forEach(el=>el.disabled=true);$('result').hidden=false;$('result').innerHTML=`<h2>${esc(reason)}</h2><div class="score">${score} / 33</div><p>Без ответа: ${current.length-Object.keys(answers).length}. Зелёным отмечен правильный вариант, красным — остальные. Балл рассчитан по первым ответам.</p><table><thead><tr><th>Лекция</th><th>Верно</th><th>Повторить вопросы</th></tr></thead><tbody>${stats.map((s,i)=>`<tr><td>${String(i).padStart(2,'0')} · ${esc(titles[i])}</td><td>${s.correct} / ${s.total}</td><td>${s.miss.map(n=>`<a href="#q-${current[n-1].id}">${n}</a>`).join(', ')||'—'}</td></tr>`).join('')}</tbody></table><p>Прочитай разбор под каждым вопросом и вернись к исходному слайду по ошибкам. Этот результат не предсказывает реальный экзаменационный балл.</p>`;$('finishBottom').hidden=true;$('finishTop').hidden=true;$('again').hidden=false;$('result').scrollIntoView({block:'start'});}
$('questions').addEventListener('change',e=>{if(submitted)return;if(e.target.matches('input[type=radio]')){const x=current.find(x=>x.id===e.target.name);if(!x||answers[x.id]!==undefined)return;answers[x.id]=Number(e.target.value);revealAnswer(x);updateProgress()}});$('questions').addEventListener('submit',e=>e.preventDefault());$('start').addEventListener('click',start);$('finishTop').addEventListener('click',()=>finish());$('finishBottom').addEventListener('click',()=>finish());$('again').addEventListener('click',()=>{clearInterval(interval);$('intro').hidden=false;$('statusbar').hidden=true;$('jump').hidden=true;$('result').hidden=true;$('questions').innerHTML='';$('bottom').hidden=true;window.scrollTo({top:0})});
</script></html>'''
(root/'Trainer.html').write_text(page.replace('__BANK__',json.dumps(bank,ensure_ascii=False).replace('</','<\\/')))
print('Trainer.html built:',(root/'Trainer.html').stat().st_size,'bytes')
